// Fork of "test shader crash" by byt3_m3chanic. https://shadertoy.com/view/43dfRj





float pModPolar(inout vec2 p, float a) { // no bug with: in p, or out p, or no float a 

    return length(p);
}

vec2 map(vec3 r) {
    r.xy *= mat2(1);                     // no bug without this

    pModPolar(r.xy,mod(r.z,6.));                                 // bug on OpenGL/nvidia
 // pModPolar(r.xy,r.z);                                         // works
 // vec2 v = r.xy; pModPolar(v,mod(r.z,6.)<3.?6.:3.);r.xy = v;   // works
    return r.xy;
}

void mainImage( out vec4 O, vec2 F )
{
    O.xy = map(F.xyy);                    // no bug if map() is  inlined
    vec3 r = F.xyy;
}
